#ifndef PBNFC_MARKUP_LEXER_H
#define PBNFC_MARKUP_LEXER_H

#include "diagnostics.h"

#include <stdbool.h>
#include <stddef.h>

typedef enum {
    PBNFC_MARKUP_TOKEN_EOF = 0,
    PBNFC_MARKUP_TOKEN_LESS_THAN,
    PBNFC_MARKUP_TOKEN_GREATER_THAN,
    PBNFC_MARKUP_TOKEN_SLASH,
    PBNFC_MARKUP_TOKEN_EQUALS,
    PBNFC_MARKUP_TOKEN_IDENT,

    /* Short names keep punctuation tokens convenient for scanner clients. */
    PBNFC_MARKUP_TOKEN_LT = PBNFC_MARKUP_TOKEN_LESS_THAN,
    PBNFC_MARKUP_TOKEN_GT = PBNFC_MARKUP_TOKEN_GREATER_THAN,
    PBNFC_MARKUP_TOKEN_EQUAL = PBNFC_MARKUP_TOKEN_EQUALS,
    PBNFC_MARKUP_TOKEN_IDENTIFIER = PBNFC_MARKUP_TOKEN_IDENT
} PbnfcMarkupTokenKind;

/* A token is a non-owning view into the source supplied to the lexer. */
typedef struct {
    PbnfcMarkupTokenKind kind;
    PbnfcLocation location;
    const char *text;
    size_t length;
} PbnfcMarkupToken;

typedef struct {
    const char *source;
    size_t length;
    size_t offset;
    size_t line;
    size_t column;
    bool in_tag;
    bool failed;
} PbnfcMarkupLexer;

/* Initialize a core tag scanner. The source buffer remains caller-owned. */
void pbnfc_markup_lexer_init(PbnfcMarkupLexer *lexer,
                             const char *source,
                             size_t length);

/* Returns true for each token, including EOF, and false after malformed input. */
bool pbnfc_markup_lexer_next(PbnfcMarkupLexer *lexer,
                             PbnfcMarkupToken *token);

bool pbnfc_markup_lexer_failed(const PbnfcMarkupLexer *lexer);

const char *pbnfc_markup_token_kind_name(PbnfcMarkupTokenKind kind);

#endif
#include "markup_lexer.h"

static bool is_layout_space(unsigned char character)
{
    return character == (unsigned char)' ' ||
           character == (unsigned char)'\t' ||
           character == (unsigned char)'\v' ||
           character == (unsigned char)'\f' ||
           character == (unsigned char)'\r' ||
           character == (unsigned char)'\n';
}

static bool is_identifier_start(unsigned char character)
{
    return (character >= (unsigned char)'A' &&
            character <= (unsigned char)'Z') ||
           (character >= (unsigned char)'a' &&
            character <= (unsigned char)'z') ||
           character == (unsigned char)'_' ||
           character == (unsigned char)':';
}

static bool is_identifier_part(unsigned char character)
{
    return is_identifier_start(character) ||
           (character >= (unsigned char)'0' &&
            character <= (unsigned char)'9') ||
           character == (unsigned char)'.' ||
           character == (unsigned char)'-';
}

static unsigned char current_character(const PbnfcMarkupLexer *lexer)
{
    return (unsigned char)lexer->source[lexer->offset];
}

static void advance_one(PbnfcMarkupLexer *lexer)
{
    unsigned char character = current_character(lexer);

    ++lexer->offset;
    if (character == (unsigned char)'\n') {
        ++lexer->line;
        lexer->column = 1U;
    } else {
        ++lexer->column;
    }
}

static void skip_layout_space(PbnfcMarkupLexer *lexer)
{
    while (lexer->offset < lexer->length &&
           is_layout_space(current_character(lexer))) {
        advance_one(lexer);
    }
}

static void set_token(PbnfcMarkupToken *token,
                      PbnfcMarkupTokenKind kind,
                      PbnfcLocation location,
                      const char *text,
                      size_t length)
{
    token->kind = kind;
    token->location = location;
    token->text = text;
    token->length = length;
}

static bool fail_lexer(PbnfcMarkupLexer *lexer)
{
    lexer->failed = true;
    return false;
}

void pbnfc_markup_lexer_init(PbnfcMarkupLexer *lexer,
                             const char *source,
                             size_t length)
{
    if (lexer == NULL) {
        return;
    }
    lexer->source = source;
    lexer->length = length;
    lexer->offset = 0U;
    lexer->line = 1U;
    lexer->column = 1U;
    lexer->in_tag = false;
    lexer->failed = source == NULL && length != 0U;
}

bool pbnfc_markup_lexer_next(PbnfcMarkupLexer *lexer,
                             PbnfcMarkupToken *token)
{
    PbnfcLocation location;
    size_t start;
    unsigned char character;

    if (lexer == NULL || token == NULL || lexer->failed ||
        lexer->source == NULL) {
        return false;
    }

    skip_layout_space(lexer);
    if (lexer->offset == lexer->length) {
        if (lexer->in_tag) {
            return fail_lexer(lexer);
        }
        location.byte_offset = lexer->offset;
        location.line = lexer->line;
        location.column = lexer->column;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_EOF,
                  location,
                  lexer->source + lexer->offset,
                  0U);
        return true;
    }

    start = lexer->offset;
    location.byte_offset = start;
    location.line = lexer->line;
    location.column = lexer->column;
    character = current_character(lexer);

    if (!lexer->in_tag) {
        if (character != (unsigned char)'<') {
            return fail_lexer(lexer);
        }
        advance_one(lexer);
        lexer->in_tag = true;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_LESS_THAN,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }

    if (character == (unsigned char)'<') {
        return fail_lexer(lexer);
    }
    if (character == (unsigned char)'>') {
        advance_one(lexer);
        lexer->in_tag = false;
        set_token(token,
                  PBNFC_MARKUP_TOKEN_GREATER_THAN,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'/') {
        advance_one(lexer);
        set_token(token,
                  PBNFC_MARKUP_TOKEN_SLASH,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (character == (unsigned char)'=') {
        advance_one(lexer);
        set_token(token,
                  PBNFC_MARKUP_TOKEN_EQUALS,
                  location,
                  lexer->source + start,
                  1U);
        return true;
    }
    if (is_identifier_start(character)) {
        do {
            advance_one(lexer);
        } while (lexer->offset < lexer->length &&
                 is_identifier_part(current_character(lexer)));
        set_token(token,
                  PBNFC_MARKUP_TOKEN_IDENT,
                  location,
                  lexer->source + start,
                  lexer->offset - start);
        return true;
    }

    return fail_lexer(lexer);
}

bool pbnfc_markup_lexer_failed(const PbnfcMarkupLexer *lexer)
{
    return lexer != NULL && lexer->failed;
}

const char *pbnfc_markup_token_kind_name(PbnfcMarkupTokenKind kind)
{
    switch (kind) {
    case PBNFC_MARKUP_TOKEN_EOF:
        return "EOF";
    case PBNFC_MARKUP_TOKEN_LESS_THAN:
        return "<";
    case PBNFC_MARKUP_TOKEN_GREATER_THAN:
        return ">";
    case PBNFC_MARKUP_TOKEN_SLASH:
        return "/";
    case PBNFC_MARKUP_TOKEN_EQUALS:
        return "=";
    case PBNFC_MARKUP_TOKEN_IDENT:
        return "IDENT";
    }
    return "unknown";
}
#include "markup_lexer.h"

#include <stdio.h>
#include <string.h>

typedef struct {
    PbnfcMarkupTokenKind kind;
    size_t offset;
    size_t line;
    size_t column;
    const char *text;
} ExpectedToken;

static int fail_at(size_t index, const char *detail)
{
    (void)fprintf(stderr, "markup lexer smoke token %zu: %s\n", index, detail);
    return 1;
}

int main(void)
{
    static const char source[] =
        "<a href=target>\n"
        "  <img src=x.png/>";
    static const ExpectedToken expected[] = {
        {PBNFC_MARKUP_TOKEN_LESS_THAN, 0U, 1U, 1U, "<"},
        {PBNFC_MARKUP_TOKEN_IDENT, 1U, 1U, 2U, "a"},
        {PBNFC_MARKUP_TOKEN_IDENT, 3U, 1U, 4U, "href"},
        {PBNFC_MARKUP_TOKEN_EQUALS, 7U, 1U, 8U, "="},
        {PBNFC_MARKUP_TOKEN_IDENT, 8U, 1U, 9U, "target"},
        {PBNFC_MARKUP_TOKEN_GREATER_THAN, 14U, 1U, 15U, ">"},
        {PBNFC_MARKUP_TOKEN_LESS_THAN, 18U, 2U, 3U, "<"},
        {PBNFC_MARKUP_TOKEN_IDENT, 19U, 2U, 4U, "img"},
        {PBNFC_MARKUP_TOKEN_IDENT, 23U, 2U, 8U, "src"},
        {PBNFC_MARKUP_TOKEN_EQUALS, 26U, 2U, 11U, "="},
        {PBNFC_MARKUP_TOKEN_IDENT, 27U, 2U, 12U, "x.png"},
        {PBNFC_MARKUP_TOKEN_SLASH, 32U, 2U, 17U, "/"},
        {PBNFC_MARKUP_TOKEN_GREATER_THAN, 33U, 2U, 18U, ">"},
        {PBNFC_MARKUP_TOKEN_EOF, 34U, 2U, 19U, ""}
    };
    PbnfcMarkupLexer lexer;
    PbnfcMarkupToken token;
    size_t index;

    pbnfc_markup_lexer_init(&lexer, source, strlen(source));
    for (index = 0U;
         index < sizeof(expected) / sizeof(expected[0]);
         ++index) {
        if (!pbnfc_markup_lexer_next(&lexer, &token)) {
            return fail_at(index, "unexpected lexer failure");
        }
        if (token.kind != expected[index].kind ||
            token.location.byte_offset != expected[index].offset ||
            token.location.line != expected[index].line ||
            token.location.column != expected[index].column ||
            token.length != strlen(expected[index].text) ||
            strncmp(token.text, expected[index].text, token.length) != 0) {
            return fail_at(index, "token, lexeme, or location mismatch");
        }
    }
    if (pbnfc_markup_lexer_failed(&lexer)) {
        return fail_at(index, "lexer failed after the expected EOF");
    }
    if (!pbnfc_markup_lexer_next(&lexer, &token) ||
        token.kind != PBNFC_MARKUP_TOKEN_EOF) {
        return fail_at(index, "lexer did not remain at EOF");
    }
    return 0;
}
